int partition(int A[], int low, int high) {
    int pivot = A[high];
    int i = low;
    for (int j = low; j < high; ++j) {
        if (A[j] < pivot) {
            swap(&A[i], &A[j]);
            ++i;
        }
    }
    swap(&A[i], &A[high]);
    return i;
}

